    exp1: "付加年金とは、国民年金第1号被保険者（自営業者・フリーランス等）が月額400円の付加保険料を上乗せ納付することで、老齢基礎年金に「200円×付加保険料納付月数」が加算される制度。例えば20年（240か月）納付すると毎年48,000円が加算される。2年間受給すれば納付総額（400円×240か月＝96,000円）を回収できる「お得な制度」として知られる。",
