    svg: "<svg width=\"300\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"150\" fill=\"#f9fbe7\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#558b2f\">付加年金 元取り計算（240か月納付の場合）</text>\n  <!-- 納付総額 -->\n  <rect x=\"20\" y=\"35\" width=\"120\" height=\"35\" fill=\"#aed581\" rx=\"4\"/>\n  <text x=\"80\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" fill=\"#33691e\">納付総額</text>\n  <text x=\"80\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#33691e\">96,000円</text>\n  <!-- 矢印 -->\n  <text x=\"148\" y=\"57\" font-size=\"16\" fill=\"#558b2f\">→</text>\n  <!-- 年間受取 -->\n  <rect x=\"165\" y=\"35\" width=\"115\" height=\"35\" fill=\"#7cb342\" rx=\"4\"/>\n  <text x=\"222\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" fill=\"white\">毎年受取</text>\n  <text x=\"222\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"white\">48,000円/年</text>\n  <!-- 元取り -->\n  <rect x=\"80\" y=\"85\" width=\"140\" height=\"30\" fill=\"#558b2f\" rx=\"4\"/>\n  <text x=\"150\" y=\"104\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\" font-weight=\"bold\">2年で元が取れる</text>\n  <text x=\"150\" y=\"135\" text-anchor=\"middle\" font-size=\"10\" fill=\"#666\">400円/月上乗せ → 200円×月数で受給</text>\n</svg>",
