    exp1: "国民年金基金は、国民年金第1号被保険者（自営業者・フリーランス等）が老齢基礎年金に上乗せできる公的な年金制度。掛金は全額が社会保険料控除の対象。口数制を採用しており、加入者が口数・給付の型を選んで掛金を決める。付加年金との併用はできないが、iDeCoとの併用は可能。",
