    exp3: "国民年金基金の掛金は掛金控除（小規模企業共済等掛金控除）ではなく「社会保険料控除」に区分される点に注意。iDeCoは小規模企業共済等掛金控除。どちらも全額所得控除だが、区分が異なる。",
