    exp1: "育児休業給付は、雇用保険から支給される給付で、育休取得中の収入を補填する制度。支給額は休業開始前の賃金日額×支給日数で、育休開始から180日間は67%、181日目以降は50%に変わる。2025年以降は「出生後休業支援給付」などの追加制度も整備され、給付率が最大で実質80%程度になるケースも出てきている。",
