    exp1: "労働者災害補償保険（労災保険）は、業務上の事故・病気（業務災害）および通勤途中の事故（通勤災害）を補償する社会保険制度。保険料は全額事業主が負担し、労働者は一切負担しない。給付内容は療養補償給付（治療費全額）・休業補償給付（給与の60%・特別支給金あわせると80%）・障害補償給付・遺族補償給付などがある。",
