    q: "次の状況に当てはまるのは？",
    choices: [{"text":"ライフプランとは、人生の各段階（結婚・住宅・子育て・老後等）の目標を設定し、必要な資金と時期を整理したもの","correct":true},{"text":"ライフプランとは、老後の生活費だけを試算するためのもの","correct":false,"hint":"老後だけでなく、住宅・教育・結婚・介護など人生全体のイベントを対象とする。"}],
    exp1: "ライフプランとは、人生の節目ごとのイベント（結婚・出産・住宅購入・子どもの教育・老後・介護など）を時系列で整理し、それぞれに必要な費用・収入・貯蓄の流れを可視化したもの。FP相談の出発点となる。ライフプランをもとにキャッシュフロー表・個人バランスシートを作成し、資金計画を立てる。",
