    exp1: "健康保険・厚生年金の保険料算定の基礎となる給与の区分（等級）。毎年4〜6月に受けた報酬の平均額を一定の等級表に当てはめたものが標準報酬月額で、当年9月から翌年8月の保険料に適用される（定時決定）。給与が大きく変動した場合は随時改定（月変）もある。等級ごとの保険料額表から算定する。",
