    exp1: "16歳以上の扶養親族がいる場合に適用される所得控除。控除額は一般扶養親族（16〜18歳・23歳以上70歳未満）38万円、特定扶養親族（19〜22歳）63万円、老人扶養親族（70歳以上）は同居58万円・別居48万円。扶養親族の合計所得金額が48万円以下であることが要件。",
    exp2: "試験では「年齢区分による控除額の違い」が問われる。19〜22歳（大学生等）の特定扶養親族は教育費負担が大きいことを考慮し63万円と優遇。15歳以下は対象外という落とし穴も出題される。所得控除であるため、高所得者ほど節税効果が大きい点も理解する。",
    exp3: "「扶養控除＝配偶者控除」と混同しやすい。扶養控除は配偶者以外の扶養親族（子・親等）が対象。配偶者には配偶者控除・配偶者特別控除が別途ある。",
