    exp1: "健康保険の被扶養者とは、被保険者（会社員等）の収入で生計を維持している家族のことで、保険料を自分で負担せず医療給付が受けられる。収入要件は原則として年収130万円未満（かつ被保険者の年収の半分未満）。同居・別居で基準が一部異なる。2022年以降は従業員101人以上の企業でパート等が社会保険加入義務化となり、「106万円の壁」も生じている。",
    exp2: "試験では「被扶養者の要件（年収130万円）」が頻出。「所得税の扶養控除（合計所得48万円以下）」と「健保の被扶養者（年収130万円未満）」は別の制度・別の基準点を混同しないよう注意。税法と社会保険法は独立した判断基準を持つ。",
    exp3: "「130万円の壁」を超えると自ら国民健康保険か勤務先の社会保険に加入し保険料を負担する必要がある。扶養を外れると手取りが減る逆転現象が起きるケースがある（130万円の壁問題）。",
