    exp1: "60歳以上65歳未満の雇用保険被保険者が、60歳到達時の賃金と比べて75%未満の賃金で就業している場合に、雇用保険から支給される給付。最大で賃金の15%相当が支給される。雇用保険の被保険者期間が5年以上であることが要件。2025年度以降は給付水準が段階的に縮小される予定（最大10%へ）。",
    exp2: "試験では「高年齢雇用継続給付の対象要件」が問われる。在職中の給付（失業給付ではない）・60〜65歳未満・賃金75%未満・被保険者期間5年以上、という要件の組合せを確認する。在職老齢年金（老齢厚生年金）との同時受給も可能だが、一部調整がかかる。",
