    exp1: "雇用保険の給付体系における区分の一つで、失業した労働者を支援するための給付の総称。一般被保険者への求職者給付の中心は基本手当（いわゆる「失業手当」）。そのほか技能習得手当（受講手当・通所手当）、寄宿手当、傷病手当が含まれる。高年齢被保険者・短期雇用特例被保険者・日雇労働被保険者にはそれぞれ別の給付区分がある。",
    exp2: "試験では雇用保険の給付体系の全体像が問われる。「雇用保険の給付＝失業給付だけではない」という点を押さえる。就職促進給付（再就職手当等）・教育訓練給付・雇用継続給付（高年齢・介護）など、求職者給付以外の区分もある。「基本手当＝求職者給付の中核」と整理する。",
