    q: "次の状況に当てはまるのは？",
    choices: [{"text":"所定給付日数は離職理由（自己都合か会社都合か）・年齢・被保険者期間によって決まり、会社都合の方が一般に給付日数が多い","correct":true},{"text":"所定給付日数は全員一律で最長360日である","correct":false,"hint":"360日は特定受給資格者（会社都合等）の上限。自己都合退職者の上限は150日。一律ではない。"}],
    exp1: "雇用保険の基本手当を受給できる日数の上限。離職理由・年齢・雇用保険の被保険者期間の3要素で決まる。会社都合・倒産・解雇等による「特定受給資格者」は最大330日（45〜59歳・20年以上）、自己都合退職の一般受給資格者は最大150日（45歳以上・20年以上）。自己都合の場合は2〜3か月の給付制限期間がある（2023年改正で一定要件を満たせば1か月）。",
    exp2: "試験では「自己都合と会社都合の違い（所定給付日数・給付制限）」が問われる。自己都合＝給付日数少ない・給付制限あり、会社都合（特定受給資格者）＝給付日数多い・給付制限なし、という対比が核心。被保険者期間が短いほど給付日数も少ない点も出題される。",
    exp3: "「会社都合退職なら給付制限なし」は正しい。自己都合でも「正当な理由のある自己都合」（体調不良・配偶者の転勤等）に該当すれば給付制限が免除される場合がある。一律の扱いではない点に注意。",
