    exp1: "第1号被保険者（自営業者・学生等）が自ら納付する定額の保険料。2026年度は月額16,980円（2026年現在）。支払い方法は口座振替・クレジットカード・コンビニ払い等があり、前納（まとめ払い）すると割引がある。収入が少ない場合は全額免除・4分の3免除・半額免除・4分の1免除の免除制度を利用できる。",
    exp2: "試験では「国民年金保険料の特徴（定額）」と「免除制度の概要」が問われる。厚生年金は報酬比例（標準報酬月額×保険料率）、国民年金は定額、という対比が重要。免除を受けた期間は年金額に反映される割合が異なる（全額免除期間は2分の1・保険料納付期間は全額反映）。",
    exp3: "「免除＝保険料を払わなくていい期間」は正しいが「年金額も変わらない」は誤り。全額免除の期間は将来の年金額が減少する（納付期間の1/2相当）。追納（10年以内）することで年金額を満額に近づけられる。",
    svg: "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f8ff\" rx=\"8\"/>\n  <text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1a3a5c\">保険料免除と年金額への反映</text>\n  <rect x=\"10\" y=\"30\" width=\"65\" height=\"28\" fill=\"#2a7a3a\" rx=\"3\"/>\n  <text x=\"42\" y=\"48\" text-anchor=\"middle\" font-size=\"10\" fill=\"white\" font-weight=\"bold\">全額納付</text>\n  <text x=\"42\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" fill=\"#2a7a3a\">年金額</text>\n  <text x=\"42\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#2a7a3a\" font-weight=\"bold\">10/10</text>\n  <rect x=\"83\" y=\"30\" width=\"65\" height=\"28\" fill=\"#4a90d9\" rx=\"3\"/>\n  <text x=\"115\" y=\"44\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\" font-weight=\"bold\">1/4免除</text>\n  <text x=\"115\" y=\"56\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">（3/4納付）</text>\n  <text x=\"115\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" fill=\"#4a90d9\">年金額</text>\n  <text x=\"115\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#4a90d9\" font-weight=\"bold\">8.75/10</text>\n  <rect x=\"156\" y=\"30\" width=\"65\" height=\"28\" fill=\"#e8a020\" rx=\"3\"/>\n  <text x=\"188\" y=\"44\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\" font-weight=\"bold\">半額免除</text>\n  <text x=\"188\" y=\"56\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">（1/2納付）</text>\n  <text x=\"188\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8a020\">年金額</text>\n  <text x=\"188\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8a020\" font-weight=\"bold\">6.25/10</text>\n  <rect x=\"229\" y=\"30\" width=\"65\" height=\"28\" fill=\"#d94a4a\" rx=\"3\"/>\n  <text x=\"261\" y=\"44\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\" font-weight=\"bold\">全額免除</text>\n  <text x=\"261\" y=\"56\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">（0円）</text>\n  <text x=\"261\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" fill=\"#d94a4a\">年金額</text>\n  <text x=\"261\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#d94a4a\" font-weight=\"bold\">5/10</text>\n  <text x=\"150\" y=\"115\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">全額免除でも受給資格期間には算入される</text>\n  <text x=\"150\" y=\"130\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">追納（10年以内）で年金額を回復可能</text>\n  <text x=\"150\" y=\"150\" text-anchor=\"middle\" font-size=\"10\" fill=\"#1a3a5c\" font-weight=\"bold\">2026年度 保険料：月額16,980円（定額）</text>\n  <text x=\"150\" y=\"168\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">厚生年金：標準報酬月額×保険料率（比例）と対比</text>\n</svg>",
