    exp1: "がんの診断・入院・手術・通院等に特化した保険。主な給付は①がん診断給付金（診断確定時に一時金、100〜500万円等）②がん入院給付金（入院1日当たり）③がん手術給付金等。通常の医療保険と異なり、がんと診断された時点で診断給付金が支払われる点が特徴。加入から90日間の免責期間（責任開始前）が設けられているのが一般的。",
    exp2: "試験では「がん保険の免責期間（90日）」と「診断給付金の特徴（がん確定時に一時金）」が問われる。「医療保険に加入していればがん保険は不要」という問いに対しては、医療保険はがんの長期入院・高額治療費に対応しにくい場合があるため、がん保険の独自性がある。",
    exp3: "免責期間中に加入者ができる事（他の疾病給付など）と不可能な事（がん関連の給付）を混同しないよう注意。また「がん再発」に対する給付も商品によって異なる（再診断給付金等）。",
