    exp1: "民間の保険会社が提供する介護保険で、公的介護保険制度の補完を目的とする。要介護認定（公的）や保険会社独自の認定基準に応じて、介護一時金または介護年金の形で給付が行われる。公的介護保険の自己負担（1〜3割）や、施設入居費・特定福祉用具購入費など公的保険でカバーされない費用への対応に向く。",
    exp2: "試験では「公的介護保険（社会保険）と民間介護保険の違い」が問われる。公的＝40歳以上強制加入・要介護認定に基づく現物給付中心、民間＝任意加入・現金給付も多い、という対比を整理する。また「どちらの介護保険か」を文脈から判断することが求められる。",
    exp3: "「介護保険」という言葉だけでは公的か民間か判断できない。問題文の文脈（「社会保険の介護保険」「民間保険会社の介護保険」）を確認する。FP試験でも両者の違いの問いは頻出。",
