    scenario: "32歳の自営業者・武田さんが「長期入院したら収入がゼロになる。自分には傷病手当金がない」と気づき、就業不能保険を検討している。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"就業不能保険は病気・ケガで長期間働けない状態になった場合に毎月給付金を受け取れる保険で、自営業者にも適している","correct":true},{"text":"就業不能保険は死亡した場合にのみ保険金が支払われる生命保険の一種である","correct":false,"hint":"死亡給付ではなく「就業不能状態（生存中に働けない状態）」への給付が特徴。死亡保険とは別。"}],
    exp1: "病気やケガによる長期入院・在宅療養等で就業不能状態が一定期間続いた場合に、毎月給付金（収入補填）が支払われる保険。会社員には傷病手当金（最長1年6か月）があるが、自営業者には公的な収入補償がないため特に重要な保険。精神疾患（うつ病等）が給付対象に含まれる商品も増えている。",
    exp2: "試験では「就業不能保険の特徴と所得補償保険との違い」が問われる。就業不能保険は生命保険会社の商品、所得補償保険は損害保険会社の商品（実損補填型）という区別がある。「死亡したらもらえる」ではなく「生存しているが働けない状態でもらえる」という点が核心。",
    exp3: "就業不能保険は「就業不能状態」の定義が商品によって異なる。「入院中のみ」「在宅療養も含む」「所定の状態（要介護等）」など条件を確認する必要がある。試験では「就業不能状態の定義は商品ごとに異なる」という記述が正解になりやすい。",
