    scenario: "40代自営業者の木下さんが骨折で3か月間仕事ができなくなった。健康保険の傷病手当金は会社員向けで自分には適用されないと知り、損害保険の所得補償保険に加入していたことを思い出した。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"所得補償保険は損害保険の一種で、業務外の病気・ケガによる収入減少を実損補填する保険である","correct":true},{"text":"所得補償保険は生命保険会社が取り扱う保険で、死亡時に収入を補填する","correct":false,"hint":"所得補償保険は損害保険会社の商品。生命保険会社が提供する類似商品は「就業不能保険」。死亡給付ではなく就業不能時の収入補填。"}],
    exp1: "業務外の病気やケガにより就業が不能になった場合に、実際の収入減少額（実損）を補填する損害保険の一種。保険期間中の収入減少を実損ベースで補償するため、収入が変動する自営業者にも利用しやすい。免責期間（待機期間、一般的に60日程度）経過後から給付が開始される。",
    exp2: "試験では「所得補償保険（損保）vs就業不能保険（生保）」の区別が問われる。損保の所得補償保険は実損補填・損害保険料控除の対象、生保の就業不能保険は定額給付・生命保険料控除の対象、という対比を整理する。また「業務上の災害は労災保険が優先」という点も確認する。",
    exp3: "所得補償保険は「実損補填」のため、実際に収入がなければ給付も少なくなる場合がある。定額給付型の就業不能保険とは給付の考え方が異なる。どちらが適しているかはケースバイケース。",
