    scenario: "35歳会社員の中田さんが年末調整で「一般生命保険料」「個人年金保険料」「介護医療保険料」の3種類の証明書を提出した。「この3つって別々に控除されるの？」と確認している。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"2012年以降の新契約では生命保険料控除は3区分（一般・個人年金・介護医療）に分かれ、各区分で最大4万円（所得税）の控除が受けられる","correct":true},{"text":"生命保険料控除は種類にかかわらず全保険料をまとめて一つの控除として計算する","correct":false,"hint":"3区分独立計算が新契約ルール。旧契約は2区分（一般・個人年金）で各最大5万円。"}],
    exp1: "生命保険料を支払った場合に適用される所得控除（所得税・住民税）。2012年1月以降の新契約では①一般生命保険料控除（死亡保険等）②個人年金保険料控除③介護医療保険料控除（医療保険・がん保険等）の3区分に分類され、所得税では各区分最大4万円・合計最大12万円の控除が受けられる。住民税は各区分最大2.8万円・合計最大7万円。",
    exp2: "試験では「3区分の内訳」「控除限度額（所得税4万円・住民税2.8万円）」が問われる。旧契約（2011年以前）は2区分・各最大5万円というルールと混在する場合の計算問題も出題される。所得控除（課税所得を減らす）であるため、税率が高い人ほど節税効果が大きい。",
    exp3: "生命保険料控除は「所得控除」であり「税額控除」ではない。住宅ローン控除（税額控除）とは効果の大きさが異なる。控除額から税率をかけて節税額を計算する。",
    svg: "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f8ff\" rx=\"8\"/>\n  <text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1a3a5c\">生命保険料控除（新契約）3区分</text>\n  <rect x=\"10\" y=\"28\" width=\"85\" height=\"50\" fill=\"#4a90d9\" rx=\"4\"/>\n  <text x=\"52\" y=\"48\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\" font-weight=\"bold\">一般生命</text>\n  <text x=\"52\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">保険料控除</text>\n  <text x=\"52\" y=\"72\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">（死亡保険等）</text>\n  <rect x=\"107\" y=\"28\" width=\"85\" height=\"50\" fill=\"#e8a020\" rx=\"4\"/>\n  <text x=\"150\" y=\"48\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\" font-weight=\"bold\">個人年金</text>\n  <text x=\"150\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">保険料控除</text>\n  <text x=\"150\" y=\"72\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">（個人年金）</text>\n  <rect x=\"204\" y=\"28\" width=\"86\" height=\"50\" fill=\"#2a7a3a\" rx=\"4\"/>\n  <text x=\"247\" y=\"48\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\" font-weight=\"bold\">介護医療</text>\n  <text x=\"247\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">保険料控除</text>\n  <text x=\"247\" y=\"72\" text-anchor=\"middle\" font-size=\"9\" fill=\"white\">（医療・介護）</text>\n  <text x=\"150\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c00\" font-weight=\"bold\">各区分 所得税：最大4万円</text>\n  <text x=\"150\" y=\"115\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c00\">合計最大12万円（所得税）</text>\n  <text x=\"150\" y=\"132\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">住民税：各2.8万円・合計7万円</text>\n  <text x=\"150\" y=\"150\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">所得控除（≠税額控除）</text>\n  <text x=\"150\" y=\"168\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">旧契約：2区分・各最大5万円</text>\n</svg>",
