    q: "次の状況に当てはまるのは？",
    choices: [{"text":"死亡保険金の課税関係は「契約者・被保険者・受取人」の組合せによって相続税・所得税・贈与税に分かれる","correct":true},{"text":"死亡保険金は受け取った人が誰であっても一律に相続税が課税される","correct":false,"hint":"契約者・被保険者・受取人が全員異なる場合は贈与税、契約者＝受取人で被保険者が異なる場合は所得税（一時所得）となる。"}],
    exp1: "死亡保険金の課税は受取人だけでなく、契約者・被保険者との関係で決まる。①契約者＝被保険者、受取人が第三者→相続税（みなし相続財産）②契約者＝受取人、被保険者が第三者→所得税（一時所得）③契約者・被保険者・受取人が全員異なる→贈与税。「誰の財産が誰に移転したか」という視点で覚える。",
    exp2: "試験では「組合せパターンと課税区分」の表が頻出。最も基本的なパターン①（夫が契約者兼被保険者・妻が受取人）は相続税。覚え方は「死んだ人が保険料を払っていた＝その人の財産が相続された＝相続税」。変則パターンは「税目の違い」から問われる。",
    exp3: "相続税のケース（パターン①）では、「法定相続人の数×500万円」の非課税枠が適用される。この非課税枠は所得税・贈与税の場合には適用されない。",
