    exp1: "生命保険を解約した際に契約者が受け取る金額。保険会社が積み立てた責任準備金をベースに、解約控除・経過年数等を考慮して算出される。掛け捨て型（定期保険）はほとんどなく、貯蓄性のある終身保険・養老保険等で高くなる。加入直後は低く、長期保有ほど高まる傾向がある。契約者貸付（解約返戻金の一定割合を借入）の担保にもなる。",
