    exp1: "入院給付金とは、医療保険において被保険者が入院した場合に支払われる給付金で、入院1日あたりの定額（日額）で設定される。免責日数（入院開始から給付対象外となる日数）が設定されている場合、免責期間を超えた日数分のみ給付される。また、支払限度日数（1回の入院・通算の入院で支払われる上限日数）も重要な条件。",
    exp2: "「入院給付金の計算」は頻出。公式：受取額＝日額×（実入院日数−免責日数）。ただし（実入院日数−免責日数）が支払限度日数を超えた場合は上限で打ち切り。免責日数の有無と支払限度日数の確認が解法の手順。",
    exp3: "「入院初日から給付」と「免責あり」を混同しやすい。近年の医療保険では「1日目（入院初日）から給付」を売りにする商品も多いが、試験では「免責日数3日」等の設定で計算させるケースが多い。条件を必ず読む。",
