    exp1: "保険料は2つの要素で構成される。①純保険料：将来の保険金・給付金の支払財源。収支相等の原則（保険料総額＝保険金総額）に基づき、予定死亡率・予定利率から計算される。②付加保険料：保険会社の事業運営に必要な経費（人件費・代理店手数料・広告費等）と利益の財源。保険料＝純保険料＋付加保険料。",
