    exp1: "個人向け国債は個人専用の国債で、変動金利10年・固定金利5年・固定金利3年の3種類がある。最低保証利率は年0.05%（2026年現在）で、金利がゼロになることはない。購入は1万円から1万円単位。中途換金は発行から1年経過後に可能で、換金時に「直前2回分の利子×0.79685（税引後）」が差し引かれる。",
    exp2: "「個人向け国債の3種類の特徴」は頻出。変動10年＝半年ごとに金利見直し・金利上昇に強い。固定5年＝5年間金利固定・中期運用向き。固定3年＝3年間金利固定・短期運用向き。金利上昇局面では変動10年が有利になるという判断が試験で問われる。",
    exp3: "「個人向け国債は途中で換金できない」という誤解に注意。発行から1年経過後なら換金可能。ただし直前2回分の利子が没収されるため、1〜2年での換金はほぼ利益が出ない。長期保有前提で設計された商品。",
