    exp1: "配当性向とは、当期純利益のうち配当金として株主に還元する割合を示す指標。計算式は「配当総額（または1株配当）÷当期純利益（または1株利益）×100（%）」。100%を超えると利益以上を配当していることになり、財務的に持続困難なサインとなる。",
    exp2: "試験では配当利回りとの混同が狙われる。配当性向は「利益のうち配当に回す割合」、配当利回りは「株価に対する配当の割合」と明確に区別する。「高配当性向＝株主への還元意識が高い」という解釈も出題される。",
    exp3: "配当利回りと混同しやすい。配当利回りは株価との比較、配当性向は純利益との比較。分母が「株価か純利益か」で区別できる。",
