    exp1: "投資信託とは、多数の投資家から集めた資金を一つにまとめ、ファンドマネージャー（運用の専門家）が株式・債券・不動産等に分散投資する金融商品。少額から分散投資が可能で、個別株を買う知識がなくてもプロに委託できるメリットがある。ただし元本保証は一切なく、預金保険の対象外。",
    exp2: "試験頻出の誤り選択肢が「元本保証がある」「預金保険で保護される」。どちらも誤り。また、運用コストとして信託報酬（年率）がかかる点も出題ポイント。公社債投資信託・株式投資信託の違い、オープン型・クローズド型の区別も確認する。",
    exp3: "銀行預金と混同しやすい。預金は元本保証あり・預金保険対象。投資信託は元本保証なし・預金保険対象外。窓口が銀行でも投資信託は「預金ではない」と明示される。",
