    exp1: "アクティブ運用とは、ファンドマネージャーが銘柄選択・売買タイミングを積極的に判断し、ベンチマーク（日経平均など市場平均）を上回る収益を狙う運用スタイル。調査・分析コストがかかるため、信託報酬はパッシブ運用より高くなる傾向がある。必ずしも市場平均を上回るとは限らない。",
