    exp1: "パッシブ運用（インデックス運用）とは、日経平均株価やTOPIXなどのベンチマーク指数に連動した運用成果を目指すスタイル。銘柄選択の調査・分析が不要なため、信託報酬がアクティブ運用より低く抑えられる。長期積立に向いており、つみたてNISAの対象商品の多くがこの運用方式。",
