    exp1: "インフレリスク（購買力リスク）とは、物価が上昇（インフレ）した場合に、金融資産の名目金額は変わらなくても実質的な購買力（物やサービスを買える量）が低下するリスク。例えば金利0.01%の預金に対してインフレ率が2%であれば、実質利回りはマイナスになり資産価値が実質的に目減りする。",
