    exp1: "流動性リスクとは、保有する資産を必要なときに希望する価格・タイミングで換金（売買）できないリスク。不動産・未上場株式・一部の債券等は売買できる相手（市場）が限られるため流動性が低い。流動性が低い資産は換金性の低さを補うため、一般的に期待収益率（プレミアム）が高くなる傾向がある。",
