    exp2: "「定額購入＝ドルコスト平均法」「定口購入＝定口購入法」の対比が頻出。「ドルコストは価格が下がると多く買える＝平均単価低下効果あり」。一方「定口は価格に関わらず同じ数量を買い続ける」点が違い。計算問題では平均購入単価を求める問題が出る。",
    exp3: "「ドルコスト＝損をしない」は誤り。価格がずっと下がり続ける場合は損失になることもある。あくまで「高値づかみを避けやすい・平均単価を下げやすい」手法。",
    svg: "<svg width=\"300\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"170\" fill=\"#f0f9ff\" rx=\"8\"/>\n  <text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1a3a6b\">ドルコスト平均法のイメージ（毎月1万円）</text>\n  <text x=\"20\" y=\"40\" font-size=\"10\" fill=\"#555\">月</text>\n  <text x=\"70\" y=\"40\" font-size=\"10\" fill=\"#555\">1月</text>\n  <text x=\"130\" y=\"40\" font-size=\"10\" fill=\"#555\">2月</text>\n  <text x=\"190\" y=\"40\" font-size=\"10\" fill=\"#555\">3月</text>\n  <text x=\"20\" y=\"60\" font-size=\"10\" fill=\"#555\">価格</text>\n  <text x=\"65\" y=\"60\" font-size=\"10\" fill=\"#555\">1,000円</text>\n  <text x=\"125\" y=\"60\" font-size=\"10\" fill=\"#e74c3c\" font-weight=\"bold\">500円↓</text>\n  <text x=\"188\" y=\"60\" font-size=\"10\" fill=\"#27ae60\" font-weight=\"bold\">2,000円↑</text>\n  <text x=\"20\" y=\"80\" font-size=\"10\" fill=\"#555\">購入口数</text>\n  <text x=\"70\" y=\"80\" font-size=\"10\" fill=\"#555\">10口</text>\n  <text x=\"130\" y=\"80\" font-size=\"10\" fill=\"#e74c3c\" font-weight=\"bold\">20口↑</text>\n  <text x=\"190\" y=\"80\" font-size=\"10\" fill=\"#27ae60\">5口↓</text>\n  <line x1=\"10\" y1=\"90\" x2=\"290\" y2=\"90\" stroke=\"#ddd\" stroke-width=\"1\"/>\n  <text x=\"20\" y=\"110\" font-size=\"10\" fill=\"#555\">合計：35口　投資額：3万円</text>\n  <text x=\"20\" y=\"130\" font-size=\"10\" fill=\"#555\">平均購入単価：30,000÷35 ≒ 857円</text>\n  <rect x=\"10\" y=\"140\" width=\"280\" height=\"22\" fill=\"#4a90d9\" rx=\"5\"/>\n  <text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\" font-weight=\"bold\">市場平均（1,167円）より低い平均単価を実現</text>\n</svg>",
