    exp1: "定口購入法とは、毎回決まった口数（定量）で金融商品を購入し続ける方法。価格が高い月は投資金額が多くなり、価格が安い月は投資金額が少なくなる。ドルコスト平均法（定額購入）と比較して「高値のときに多く投資してしまう」点でコスト抑制効果は劣るとされる。",
