    exp1: "オプション取引とは、ある資産（原資産）を将来の一定期日に一定の価格（権利行使価格）で売買する「権利」を取引するデリバティブ（金融派生商品）。コール・オプション＝買う権利（相場上昇で有利）、プット・オプション＝売る権利（相場下落で有利）。権利を行使するかどうかは購入者が選択できる。",
