    exp1: "先物取引とは、将来の一定期日に一定の数量・価格で原資産（株式指数・商品・通貨等）を売買することを現時点で契約するデリバティブ取引。契約時点では資金の授受は発生しないが、決済期日には原則として契約を履行する義務がある点がオプション取引（権利）と異なる。価格変動リスクのヘッジや投機目的に利用される。",
