    exp1: "J-REIT（Japan Real Estate Investment Trust：不動産投資信託）とは、多数の投資家から集めた資金でオフィスビル・商業施設・マンション等の不動産を購入・運用し、賃料収入や売却益を投資家に分配する上場型の投資信託。東京証券取引所に上場されており、株式と同様にリアルタイムで売買可能。数万円程度の少額から不動産投資に参加できる。",
