    exp1: "仕組預金とは、銀行が設計した特殊な定期預金。通常の定期預金より高い金利が設定される代わりに、満期日が銀行の判断で延長される（コーラブル預金）・為替レートに連動して元本が外貨で返ってくるなどの特約が付く。中途解約が制限される場合が多く、流動性リスクに注意が必要。預金保険の対象だが、元本が外貨で返却される場合は実質的な円換算額が変動する可能性がある。",
