    exp1: "旧つみたてNISA（2023年以前）は年間投資枠40万円・非課税期間20年・長期積立向け投資信託限定の制度。2024年から新NISAに制度が移行し、旧制度での新規投資は2023年末で終了。旧口座で積み立てた分は非課税期間（最大20年）が終了するまでそのまま継続適用される。新NISAと別管理であり、旧口座の資産が新NISA口座に引き継がれるわけではない。",
    exp2: "「旧NISA＝2023年で新規投資終了・既存分は継続」「新NISA＝2024年開始・別管理」の時系列整理が試験ポイント。旧一般NISA（年120万円・5年）と旧つみたてNISA（年40万円・20年）の数値の違いも確認する。",
    exp3: "「旧NISAが新NISAに自動移行した」「旧口座が消える」という誤解が多い。旧制度の資産は非課税期間終了まで維持され、新NISAとは別の口座として並存する。",
