    exp2: "「給与所得（収入−給与所得控除）」と「事業所得（収入−必要経費）」を並べて覚える。青色申告特別控除（65万円・55万円・10万円）の区分も試験頻出。事業所得の赤字は給与所得・利子所得等と損益通算できる。",
    exp3: "「事業収入＝事業所得」と誤解しやすい。必ず「収入−経費＝所得」という計算を経る。給与所得控除（概算）と違い、事業所得は実際の経費を計上できる点が大きな特徴。",
