    scenario: "60代退職予定者の自分。勤続38年で退職金2,500万円を受け取ることになった。「退職金には税金がかかる」と聞いたが、どう計算するのか、会社の経理担当に聞いても「控除があるから少ない」としか教えてもらえず、自分でも理解したい。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"退職所得＝（退職収入−退職所得控除）×1/2","correct":true},{"text":"退職所得＝退職収入−退職所得控除（1/2しない）","correct":false,"hint":"退職所得は必ず1/2にする計算が正しい。1/2を忘れると課税額が倍になる誤り。"}],
    exp1: "退職所得は「（退職収入－退職所得控除）×1/2」で求める。退職所得控除は勤続20年以下なら40万円×勤続年数（最低80万円）、20年超なら800万円＋70万円×（勤続年数－20年）。勤続38年なら800万円＋70万円×18年＝2,060万円の控除となり、課税対象は大幅に圧縮される。他の所得と合算せず分離課税。",
    exp2: "試験では退職所得控除額の計算と、退職所得の計算式（×1/2）がセットで問われる。勤続年数が20年の境界をまたぐ問題が頻出。「退職金は税金がほとんどかからない」という印象は、この大きな控除と1/2課税のおかげ。",
    exp3: "×1/2を忘れた計算をひっかけの選択肢として出題される。公式は「（収入−控除）÷2」と暗記する。\n\n<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">退職所得の計算</text>\n  <rect x=\"20\" y=\"35\" width=\"260\" height=\"30\" fill=\"#c8e6c9\" rx=\"5\"/>\n  <text x=\"150\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1b5e20\">退職収入 2,500万円</text>\n  <text x=\"150\" y=\"85\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\">− 退職所得控除 2,060万円</text>\n  <line x1=\"30\" y1=\"95\" x2=\"270\" y2=\"95\" stroke=\"#888\" stroke-width=\"1\"/>\n  <text x=\"150\" y=\"112\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\">＝ 440万円 × 1/2</text>\n  <line x1=\"30\" y1=\"122\" x2=\"270\" y2=\"122\" stroke=\"#888\" stroke-width=\"1\"/>\n  <rect x=\"60\" y=\"130\" width=\"180\" height=\"32\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"151\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b5e20\">退職所得 220万円</text>\n</svg>",
    svg: "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">退職所得の計算</text>\n  <rect x=\"20\" y=\"35\" width=\"260\" height=\"30\" fill=\"#c8e6c9\" rx=\"5\"/>\n  <text x=\"150\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1b5e20\">退職収入 2,500万円</text>\n  <text x=\"150\" y=\"85\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\">− 退職所得控除 2,060万円</text>\n  <line x1=\"30\" y1=\"95\" x2=\"270\" y2=\"95\" stroke=\"#888\" stroke-width=\"1\"/>\n  <text x=\"150\" y=\"112\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\">＝ 440万円 × 1/2</text>\n  <line x1=\"30\" y1=\"122\" x2=\"270\" y2=\"122\" stroke=\"#888\" stroke-width=\"1\"/>\n  <rect x=\"60\" y=\"130\" width=\"180\" height=\"32\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"151\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b5e20\">退職所得 220万円</text>\n</svg>",
