    q: "次の状況に当てはまるのは？",
    choices: [{"text":"勤続20年超は800万円＋70万円×（勤続年数－20年）で控除額が大きくなる","correct":true},{"text":"勤続年数にかかわらず退職所得控除は一律40万円×勤続年数で計算する","correct":false,"hint":"20年超の部分は70万円/年に増額される。一律40万円は誤り。"}],
    exp1: "退職所得控除の計算式は勤続年数で変わる。20年以下は「40万円×勤続年数（最低80万円）」、20年超は「800万円＋70万円×（勤続年数－20年）」。Aさん（18年）は40万円×18年＝720万円、Bさん（25年）は800万円＋70万円×5年＝1,150万円。5年の差が430万円の控除差となる。長期勤続者ほど有利な設計になっている。",
    exp2: "試験では20年境界での計算式の切り替えが頻出。「勤続22年の退職所得控除はいくらか」という計算問題では800万円＋70万円×2年＝940万円が正解。20年ちょうどは20年以下の式を使う点も注意。",
    exp3: "「20年超えたら70万円に上がる」という切り替えを忘れると計算が全部狂う。20年の境界線を必ず意識する。\n\n<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">退職所得控除の計算式</text>\n  <rect x=\"15\" y=\"35\" width=\"270\" height=\"40\" fill=\"#c8e6c9\" rx=\"5\"/>\n  <text x=\"150\" y=\"52\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">勤続20年以下</text>\n  <text x=\"150\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">40万円 × 勤続年数（最低80万円）</text>\n  <rect x=\"15\" y=\"85\" width=\"270\" height=\"40\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"102\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">勤続20年超</text>\n  <text x=\"150\" y=\"118\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">800万円 ＋ 70万円×（年数－20年）</text>\n  <text x=\"150\" y=\"152\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">例）25年：800万＋70万×5＝1,150万円</text>\n  <text x=\"150\" y=\"170\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">例）18年：40万×18＝720万円</text>\n</svg>",
    svg: "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">退職所得控除の計算式</text>\n  <rect x=\"15\" y=\"35\" width=\"270\" height=\"40\" fill=\"#c8e6c9\" rx=\"5\"/>\n  <text x=\"150\" y=\"52\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">勤続20年以下</text>\n  <text x=\"150\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">40万円 × 勤続年数（最低80万円）</text>\n  <rect x=\"15\" y=\"85\" width=\"270\" height=\"40\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"102\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">勤続20年超</text>\n  <text x=\"150\" y=\"118\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">800万円 ＋ 70万円×（年数－20年）</text>\n  <text x=\"150\" y=\"152\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">例）25年：800万＋70万×5＝1,150万円</text>\n  <text x=\"150\" y=\"170\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">例）18年：40万×18＝720万円</text>\n</svg>",
