    exp1: "一時所得は「（収入－支出金額－特別控除50万円）×1/2」が課税対象。この例では（200万円－140万円－50万円）×1/2＝5万円が課税対象となる。総合課税なので他の所得と合算して申告。満期保険金・競馬の払戻金・懸賞当選金なども一時所得に該当する。",
    exp2: "試験では「特別控除50万円がある」「課税対象は1/2」の2点が問われる。退職所得も1/2課税なので混同しやすいが、退職所得は分離課税、一時所得は総合課税という違いがある。",
    exp3: "50万円控除を忘れた計算や、1/2にしない計算がひっかけ選択肢として頻出。「50万円引いてさらに半分」と確実に覚える。\n\n<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">一時所得の計算（例）</text>\n  <text x=\"150\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">満期保険金 200万円</text>\n  <text x=\"150\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">－ 払込保険料 140万円</text>\n  <text x=\"150\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">－ 特別控除 50万円</text>\n  <line x1=\"30\" y1=\"98\" x2=\"270\" y2=\"98\" stroke=\"#888\" stroke-width=\"1\"/>\n  <text x=\"150\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">＝ 10万円 × 1/2</text>\n  <line x1=\"30\" y1=\"125\" x2=\"270\" y2=\"125\" stroke=\"#888\" stroke-width=\"1\"/>\n  <rect x=\"70\" y=\"133\" width=\"160\" height=\"30\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"153\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b5e20\">課税対象 5万円</text>\n</svg>",
    svg: "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">一時所得の計算（例）</text>\n  <text x=\"150\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">満期保険金 200万円</text>\n  <text x=\"150\" y=\"68\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">－ 払込保険料 140万円</text>\n  <text x=\"150\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">－ 特別控除 50万円</text>\n  <line x1=\"30\" y1=\"98\" x2=\"270\" y2=\"98\" stroke=\"#888\" stroke-width=\"1\"/>\n  <text x=\"150\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">＝ 10万円 × 1/2</text>\n  <line x1=\"30\" y1=\"125\" x2=\"270\" y2=\"125\" stroke=\"#888\" stroke-width=\"1\"/>\n  <rect x=\"70\" y=\"133\" width=\"160\" height=\"30\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"153\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b5e20\">課税対象 5万円</text>\n</svg>",
