    exp1: "雑所得とは、利子・配当・不動産・事業・給与・退職・山林・譲渡・一時の9種類に該当しない所得の総称。公的年金等・副業収入・FX取引の利益（申告分離を除く場合）などが該当する。公的年金等には別途「公的年金等控除」が設けられており、65歳以上か未満かによって控除額が異なる。",
    exp2: "試験では「雑所得に該当するものはどれか」という形が頻出。公的年金や副業収入が雑所得に区分される点を押さえる。雑所得は損益通算の対象外（他の所得と損失を相殺できない）点も重要。",
    exp3: "「副業＝事業所得」ではない。事業所得と認められるには継続・反復・独立の3要件が必要。規模が小さければ雑所得になる。",
