    exp1: "譲渡所得は「収入金額－（取得費＋譲渡費用）」で計算する。取得費には購入価格のほか不動産取得税・登記費用なども含まれる。不動産の譲渡は分離課税で、所有期間5年以下が「短期譲渡（税率39.63%）」、5年超が「長期譲渡（税率20.315%）」。この例では4,500万円－（2,800万円＋100万円）＝1,600万円が課税対象となる。",
