    exp1: "損益通算とは、特定の所得が赤字（損失）になった場合に、他の種類の所得の黒字と相殺できる仕組み。原則として通算できるのは「不動産所得・事業所得・山林所得・譲渡所得」の4種類の損失。この例では事業所得－300万円と不動産100万円・給与50万円を合算すると合計所得は－150万円となり、課税所得をゼロにできる。",
    exp2: "試験では「損益通算できる所得の種類（不・事・山・譲）」と「損益通算できない所得（給与・雑・配当・一時は損失を通算不可）」の区別が頻出。不動産所得の損失でも「土地取得の借入金利子部分」は通算不可という例外もある。",
    exp3: "給与所得や雑所得が赤字になっても損益通算には使えない。「損益通算できる＝不・事・山・譲の4種のみ」と覚える。",
