    exp1: "小規模企業共済等掛金控除は、iDeCo（個人型確定拠出年金）や小規模企業共済・企業型確定拠出年金（マッチング拠出分）の掛金を支払った全額を所得から控除できる制度。自営業者のiDeCoの掛金上限は年間81万6,000円（月6万8,000円）で、掛けた分だけ丸ごと所得から引ける。節税効果が高く、老後資金の積立と節税を同時に実現できる。",
