    cat: "タックス",
    freq: "high",
    diff: "mid",
    keyword: "3区分・各最大4万円・合計最大12万円",
    scenario: "30代会社員（共働き）の自分。生命保険料・医療保険料・個人年金保険料の3種類の保険に加入している。年末調整の生命保険料控除欄を書こうとしたら「一般・介護医療・個人年金の3区分」とあり、どう書けばいいか迷っている。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"生命保険料控除は一般・介護医療・個人年金の3区分で各最大4万円、合計最大12万円","correct":true},{"text":"生命保険料控除は保険の種類にかかわらず一括で最大5万円","correct":false,"hint":"旧制度（2011年以前）の数値との混同。現行は3区分・各4万円・合計最大12万円。"}],
    exp1: "2012年1月以降に締結した新契約の生命保険料控除は3区分に分かれる。①一般生命保険料控除（死亡保険等）、②介護医療保険料控除（医療・介護等）、③個人年金保険料控除（個人年金保険）。各区分の控除額は年間保険料に応じて計算し、各区分最大4万円、3区分合計で最大12万円まで所得から控除できる。",
    exp2: "試験では「区分数（3区分）」「各区分の上限（4万円）」「合計上限（12万円）」が問われる。旧契約（2011年以前）は2区分・各5万円・合計10万円という違いも覚えておく。",
    exp3: "旧制度（2区分・各5万円）と現行制度（3区分・各4万円）の混同が最大のひっかけ。「新契約は3区分・12万円上限」と確定させる。\n\n<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">生命保険料控除（新契約）</text>\n  <rect x=\"15\" y=\"30\" width=\"270\" height=\"25\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"47\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">① 一般生命保険料控除　最大 4万円</text>\n  <rect x=\"15\" y=\"62\" width=\"270\" height=\"25\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">② 介護医療保険料控除　最大 4万円</text>\n  <rect x=\"15\" y=\"94\" width=\"270\" height=\"25\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"111\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">③ 個人年金保険料控除　最大 4万円</text>\n  <line x1=\"15\" y1=\"128\" x2=\"285\" y2=\"128\" stroke=\"#2d6a2d\" stroke-width=\"2\"/>\n  <rect x=\"60\" y=\"135\" width=\"180\" height=\"30\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b5e20\">合計 最大 12万円</text>\n</svg>",
    svg: "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">生命保険料控除（新契約）</text>\n  <rect x=\"15\" y=\"30\" width=\"270\" height=\"25\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"47\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">① 一般生命保険料控除　最大 4万円</text>\n  <rect x=\"15\" y=\"62\" width=\"270\" height=\"25\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">② 介護医療保険料控除　最大 4万円</text>\n  <rect x=\"15\" y=\"94\" width=\"270\" height=\"25\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"111\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">③ 個人年金保険料控除　最大 4万円</text>\n  <line x1=\"15\" y1=\"128\" x2=\"285\" y2=\"128\" stroke=\"#2d6a2d\" stroke-width=\"2\"/>\n  <rect x=\"60\" y=\"135\" width=\"180\" height=\"30\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b5e20\">合計 最大 12万円</text>\n</svg>",
