    exp1: "ふるさと納税は、好きな自治体に寄附することで、2,000円の自己負担を超えた額が所得税の還付と翌年住民税の控除で戻ってくる仕組み。控除の上限は年収・家族構成によって異なり、上限を超えた寄附は単なる寄附（控除なし）になる。返礼品は寄附額の30%以内の地場産品が原則。総務省の「ふるさと納税ポータル」などで上限の目安を確認できる。",
    exp2: "試験では「自己負担額は2,000円」「上限を超えると控除されない」「返礼品は寄附額の30%以内」の3点が頻出。返礼品の価値が控除額を上回ることはないという基本的な仕組みも理解する。",
