    exp1: "源泉分離課税は、支払われる際に源泉徴収（20.315%）されることで課税が完全に完結し、確定申告が一切不要な課税方式。主な対象は預貯金・公社債の利子所得。銀行口座の利子は受け取り時に20.315%が自動的に差し引かれ、残りが手取りとして入金される。申告分離課税は確定申告が必要な点で根本的に異なる。",
    exp2: "試験では「源泉分離課税の特徴（確定申告不要・源泉徴収で完結）」と「申告分離課税との違い（申告分離は確定申告必要）」が問われる。「分離」という言葉だけで混同しやすいので注意。",
    exp3: "「源泉分離と申告分離」は名前が似て非なるもの。「源泉分離＝申告不要」「申告分離＝申告必要」と割り切って覚える。",
