    exp1: "分離課税は他の所得と合算せず独立して課税する方式の総称。①源泉分離課税（預金利子等：源泉徴収で完結・申告不要）と②申告分離課税（株式譲渡・不動産譲渡等：確定申告が必要だが他の所得と分離して計算）の2種類がある。いずれも累進税率ではなく定率課税が適用される点で、総合課税とは根本的に異なる。",
    exp2: "試験では「分離課税の2種類と代表的な対象所得」の組み合わせ問題が出る。総合課税・申告分離・源泉分離の3分類を体系的に整理することが解答の鍵。",
    exp3: "「分離課税＝申告不要」と一括りにしない。申告分離は申告必要、源泉分離は申告不要、という違いを必ず区別する。",
