    exp1: "法人税は、株式会社・合同会社などの法人が得た所得（益金から損金を引いた額）に対して課される国税。税率は法人の規模によって異なり（中小法人の年間800万円以下の所得は15%・超過分は23.2%等）、地方税（法人住民税・法人事業税）を含めた「実効税率」は全体で約30%程度。個人の最高税率55%（所得税45%＋住民税10%）と比較すると、高所得になるほど法人化が有利になる場合がある。",
