    q: "次の状況に当てはまるのは？",
    choices: [{"text":"役員報酬が損金算入されるには定期同額給与等の法定要件を満たす必要がある","correct":true},{"text":"役員報酬は金額にかかわらず全額損金算入できる","correct":false,"hint":"法定要件を満たさない役員報酬は損金算入できない。無条件で全額算入はできない。"}],
