    exp1: "農地法は農地の権利移動・転用を規制し、食料生産の基盤となる農地を守るための法律。主な条文：3条許可（農地のままで売買・贈与・貸借→農業委員会の許可）、4条許可（自分の農地を農地以外に転用→都道府県知事等の許可）、5条許可（農地を転用目的で売買・貸借→都道府県知事等の許可）。相続による農地取得は許可不要だが、取得後に農業委員会への届出が必要。",
