    exp1: "土地活用の主な手法は①等価交換：デベロッパーに土地を提供し、建設された建物（マンション等）の一部を取得。自己資金不要だが所有比率が下がる。②建て貸し（事業用定期借地）：土地を長期貸出して地代収入を得る。建物所有リスクなし。③賃貸経営：自己で建物を建て賃料収入を得る。収益性は高いが建築資金・管理が必要。",
