    q: "次の状況に当てはまるのは？",
    choices: [{"text":"配偶者と子が相続人の場合、配偶者の法定相続分は1/2、子全員で1/2を均等に分ける","correct":true},{"text":"配偶者と子が相続人の場合、配偶者の法定相続分は2/3、子全員で1/3を均等に分ける","correct":false,"hint":"2/3は配偶者＋直系尊属の場合。配偶者＋子の場合は1/2ずつ。"}],
    exp1: "法定相続分（民法規定）。①配偶者＋子：配偶者1/2、子全員で1/2（均等分割）。②配偶者＋直系尊属：配偶者2/3、直系尊属全員で1/3。③配偶者＋兄弟姉妹：配偶者3/4、兄弟姉妹全員で1/4。例：遺産3,600万円、配偶者＋子2人の場合→配偶者1,800万円、子各自900万円。\n\n<svg width=\"300\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"170\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">法定相続分（配偶者＋子の場合）</text>\n  <rect x=\"15\" y=\"28\" width=\"270\" height=\"22\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">遺産総額 3,600万円</text>\n  <rect x=\"15\" y=\"56\" width=\"130\" height=\"45\" fill=\"#a5d6a7\" rx=\"4\"/>\n  <text x=\"80\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1b5e20\">配偶者（母）</text>\n  <text x=\"80\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">1/2 → 1,800万円</text>\n  <rect x=\"155\" y=\"56\" width=\"130\" height=\"45\" fill=\"#fff9c4\" rx=\"4\"/>\n  <text x=\"220\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#e65100\">子2人（均等）</text>\n  <text x=\"220\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">1/2 → 各900万円</text>\n  <text x=\"15\" y=\"118\" font-size=\"10\" fill=\"#555\">配偶者＋直系尊属：2/3 ＆ 1/3</text>\n  <text x=\"15\" y=\"133\" font-size=\"10\" fill=\"#555\">配偶者＋兄弟姉妹：3/4 ＆ 1/4</text>\n  <text x=\"15\" y=\"155\" font-size=\"9\" fill=\"#777\">※子が複数の場合は子の分を均等に分割</text>\n</svg>",
    exp2: "試験では「配偶者＋誰かによる相続分の変化」「子が複数いる場合の均等分割」「代襲相続が起きた場合の分割」が問われる。相続分は遺言で変更できるが、法定相続分は遺言がない場合の基準。遺産分割協議で全員合意すれば法定相続分と異なる分割も可能。",
    exp3: "配偶者の相続分を「常に1/2」と思いがち。正しくは「配偶者＋誰か」によって変わる。配偶者＋子なら1/2、配偶者＋直系尊属なら2/3、配偶者＋兄弟姉妹なら3/4。組み合わせで答えが変わる。",
    svg: "<svg width=\"300\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"170\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">法定相続分（配偶者＋子の場合）</text>\n  <rect x=\"15\" y=\"28\" width=\"270\" height=\"22\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">遺産総額 3,600万円</text>\n  <rect x=\"15\" y=\"56\" width=\"130\" height=\"45\" fill=\"#a5d6a7\" rx=\"4\"/>\n  <text x=\"80\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1b5e20\">配偶者（母）</text>\n  <text x=\"80\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">1/2 → 1,800万円</text>\n  <rect x=\"155\" y=\"56\" width=\"130\" height=\"45\" fill=\"#fff9c4\" rx=\"4\"/>\n  <text x=\"220\" y=\"73\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#e65100\">子2人（均等）</text>\n  <text x=\"220\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">1/2 → 各900万円</text>\n  <text x=\"15\" y=\"118\" font-size=\"10\" fill=\"#555\">配偶者＋直系尊属：2/3 ＆ 1/3</text>\n  <text x=\"15\" y=\"133\" font-size=\"10\" fill=\"#555\">配偶者＋兄弟姉妹：3/4 ＆ 1/4</text>\n  <text x=\"15\" y=\"155\" font-size=\"9\" fill=\"#777\">※子が複数の場合は子の分を均等に分割</text>\n</svg>",
