    scenario: "遺族・相続人の自分。父が亡くなり、遺産調査をすると借金（消費者金融500万円・住宅ローン残債1,000万円）がプラスの財産（預金200万円・不動産500万円）を大幅に上回っていた。相続放棄を検討している。",
