    exp1: "相続放棄は、被相続人の全ての財産（プラス・マイナス両方）の相続を拒否する意思表示。相続の開始を知った日から3か月以内（熟慮期間）に、家庭裁判所に申述書を提出する必要がある。相続放棄をすると、最初から相続人ではなかったとみなされる。放棄後の撤回は原則不可。相続放棄は単独で行えるが、限定承認は相続人全員で行う必要がある。",
    exp2: "試験では「3か月の熟慮期間」「家庭裁判所への申述が必要」「放棄後の代襲相続は発生しない」「全財産（プラス・マイナス両方）の放棄」が問われる。相続放棄の期限は「相続開始を知った日から3か月」であって、被相続人が死亡した日からではない点に注意。",
    exp3: "「借金だけ放棄してプラスの財産は受け取れる」は誤り。相続放棄はプラス・マイナス全ての財産を一括で放棄する。都合よく財産を選別する「限定承認」は可能だが、相続人全員の合意が必要で手続きが複雑。",
