    exp1: "単純承認とは、被相続人のプラス・マイナス全ての財産・権利義務を無限に引き継ぐ通常の相続承認。特別な手続きは不要で、相続の開始を知った日から3か月以内に相続放棄・限定承認をしなければ自動的に単純承認とみなされる（法定単純承認）。また、相続財産を処分した場合も単純承認とみなされる。",
    exp2: "試験では「3つの選択肢（単純承認・限定承認・相続放棄）の比較」「単純承認のみなし発生（3か月経過・財産処分）」が問われる。相続財産の一部でも処分・消費してしまうと単純承認とみなされ、後から放棄できなくなる。「葬式費用として現金を引き出した」などが実務でよく問題になる。",
