    exp1: "遺留分侵害額請求は、遺留分を侵害する遺贈・贈与等を受けた者に対して、遺留分相当額の金銭を支払うよう請求する権利。2019年7月の民法改正前は「遺留分減殺請求（現物返還）」だったが、改正後は金銭請求に一本化。請求期限：遺留分の侵害を知った日から1年以内（相続開始から10年で消滅時効）。",
    exp2: "試験では「金銭請求に一本化（2019年改正後）」「請求期限（侵害を知った日から1年）」「請求の相手方（侵害した遺贈・贈与を受けた者）」が問われる。遺留分侵害額＝遺留分額－受け取れる遺産額。遺留分を侵害されても請求しなければ権利が確保されないため、期限管理が重要。",
    exp3: "「遺留分侵害額請求で不動産を直接取り戻せる」は誤り。2019年改正で金銭請求に統一されたため、侵害した者（長男等）が金銭で支払うことになる。相手が支払えない場合は裁判所が延払いを認める場合もある（年5%の利子付き）。",
