    exp1: "検認とは、遺言書の現状（様式・内容・状態）を家庭裁判所が確認する手続き。相続人等が遺言書を発見した場合、遅滞なく家庭裁判所に提出して検認を申立てる義務がある。検認を受けずに遺言書を開封した場合は5万円以下の過料の制裁がある（遺言の効力自体は無効にならない）。検認が必要な遺言：自筆証書遺言（法務局保管を除く）・秘密証書遺言。検認が不要な遺言：公正証書遺言・法務局保管の自筆証書遺言。",
    exp2: "試験では「検認が必要な方式（自筆・秘密証書）」「検認が不要な方式（公正証書・法務局保管自筆）」「検認は遺言の有効性を確認する手続きではない（現状保全・証拠保全の手続き）」が問われる。検認後に遺言が無効と判断されることもある（形式不備など）。",
    exp3: "「検認を受ければ遺言の有効性が確定する」は誤り。検認はあくまで遺言書の現状を記録・確認する手続きで、遺言の有効性（内容の正当性）を確認するものではない。有効性は最終的に裁判で争われることもある。",
