    exp1: "遺産分割協議とは、相続人全員が話し合いにより相続財産の分割方法を決める手続き。相続人が1人でも欠けた状態で行われた協議は無効となる。協議が成立したら「遺産分割協議書」を作成し、相続人全員が実印を押印・印鑑証明書を添付することで、不動産登記や預貯金解約の手続きに使用できる。",
    exp2: "試験では「全員合意が必要かどうか」が頻出。多数決でよいという誤りの選択肢に引っかからないよう注意。また、遺言がある場合は原則として遺言が優先され、遺産分割協議なしで分割できるが、相続人全員が合意すれば遺言と異なる分割も可能な点も押さえる。",
