    exp1: "現物分割とは、相続財産をそのままの形で各相続人に割り当てる方法。預貯金や株式など分けやすい財産には向いているが、不動産1棟のみの場合は1人が取得し他の相続人が不満を持つケースも多い。3つの分割方法（現物・代償・換価）のなかで最もシンプルな方法。",
