    exp1: "代償分割とは、特定の相続人が遺産を相続し、その代わりに他の相続人に対して自己の固有財産（代償金）を支払う方法。不動産を売りたくない・事業を継続したい場合に有効な手段。代償金の支払いには取得者に十分な現金・流動資産が必要で、生命保険の死亡保険金が代償金の原資として活用されることも多い。",
    exp2: "代償分割で支払われた代償金は、支払った相続人からみると贈与ではなく「代償」。受け取った相続人に贈与税は課されない点を確認しておく。また、代償金を不動産等で支払うと譲渡所得税が発生するケースもある。",
