    exp1: "換価分割とは、遺産を売却（換価）して得た金銭を相続人間で分配する方法。使い道のない不動産や株式など、共有では管理が難しい財産に向いている。売却益が生じた場合は譲渡所得税の対象となり、取得費の計算には被相続人の取得時の情報が引き継がれる点に注意が必要。",
    exp2: "換価分割後の現金分配は法定相続分等に応じて行われる。売却時の仲介手数料・譲渡費用は売却代金から差し引いたうえで分配する。相続後すぐに売却する場合、取得費加算の特例（相続税の取得費加算）が使えるケースも覚えておく。",
    exp3: "換価分割は不動産の「売却」を伴うため、相続人全員の合意が必要。1人でも反対すれば換価分割は進められない。",
