    exp1: "相続税の申告・納付は、被相続人が死亡した日の翌日から10か月以内が期限（2026年現在）。期限内に現金一括納付が原則だが、一定条件を満たす場合は「延納（分割払い）」や「物納（財産で納付）」も認められる。申告書は被相続人の死亡時の住所地を管轄する税務署に提出する。",
