    exp1: "延納とは、相続税を金銭で一括納付できない場合に、年賦払い（分割払い）で納める制度。延納の要件は、①申告期限までに申請すること、②相続税が10万円超であること、③金銭による一括納付が困難であること、④担保を提供すること（一定額以下は不要）。延納期間中は年利1.2〜6.0%程度の利子税が加算される。",
    exp2: "延納が認められても「利子税がかかる」点が試験のポイント。また延納でも払えない場合は「物納（財産による納付）」という制度がある。延納→物納という順序も重要。不動産中心の遺産では延納・物納が現実的な選択肢になる。",
    exp3: "延納は「無利息の分割払い」ではない。利子税が発生するため総支払額は一括納付より増える。",
