    exp1: "成年後見制度は、認知症・知的障害・精神障害等で判断能力が不十分な成年者を法的に支援する制度。2種類ある。①法定後見：判断能力が低下した後に家庭裁判所が後見人を選任（後見・保佐・補助の3類型）。②任意後見：判断能力があるうちに自ら後見人を選んで公正証書で契約する制度。",
