    choices: [{"text":"類似業種比準方式は類似業種の株価・配当・利益・純資産の4要素を使って非上場株を評価する方式","correct":true},{"text":"類似業種比準方式は評価会社と類似業種の売上高を比較して評価する方式","correct":false,"hint":"売上高は比準要素ではない。配当・利益・純資産の3比準要素で計算する。"}],
    exp1: "類似業種比準方式は、評価対象の非上場会社と業種が類似する上場会社の株価を参照し、①1株当たり配当金額、②1株当たり年利益金額、③1株当たり純資産価額の3要素（比準要素）を比較することで非上場株の評価額を算出する方式。一般に純資産価額方式より評価額が低くなりやすく、相続税対策として選好されることが多い。",
    exp2: "計算式は「類似業種の株価×（A/a×0.7＋B/b×0.1＋C/c×0.2）÷2（中会社など係数が変わる）」と複雑。FP3試験では細かい計算より「何を比較するか（3要素）」と「どの会社規模に使うか」が問われる。",
    exp3: "売上高・従業員数は比準要素に含まれない。試験でよく出る誤りの選択肢なので注意。",
