    exp1: "純資産価額方式は、評価会社の相続税評価額ベースの総資産から負債を差し引いた純資産を、発行済株式数で割って1株当たりの評価額を計算する方式。上記例では（3億円－2億円）÷10万株＝1,000円/株。帳簿上の簿価ではなく「相続税評価額」を使う点が重要で、土地は路線価評価、株式は時価評価となる。",
