    exp1: "相続税の2割加算とは、相続・遺贈で財産を取得した者が「一親等の血族（子・父母）および配偶者」以外の場合に、算出された相続税額の20%を加算する制度。対象になるのは兄弟姉妹・孫（代襲相続人の孫は除く）・甥姪・内縁の配偶者など。孫養子（子の子を養子にした場合）も原則2割加算の対象。",
