    exp1: "贈与とは、贈与者が自己の財産を無償で相手方に与える意思を示し、相手方が受諾することで成立する契約。贈与契約は口頭でも成立するが、書面によらない贈与は「まだ履行していない部分」については撤回できる（民法550条）。書面で贈与契約を締結した場合は撤回不可となり、履行義務が確定する。",
    exp2: "試験では「書面/口頭」×「履行前/履行後」の組み合わせで問われる。口頭かつ未履行→撤回可、書面→撤回不可、口頭でも既に履行済み→撤回不可、というマトリックスで整理する。",
    exp3: "「口頭の贈与契約は無効」は誤り。口頭でも契約は成立する。ただし未履行なら撤回できるというだけ。",
