    exp1: "負担付贈与とは、受贈者（財産を受け取る側）に一定の義務・負担を課す条件のついた贈与。不動産の場合は相続税評価額ではなく「通常の取引価額（時価）」で評価し、そこから負担額を控除した残額が課税対象となる点が通常の贈与と異なる。ローン付き不動産の贈与は負担付贈与に該当することが多い。",
    exp2: "贈与者から見ると、負担付贈与で負担を肩代わりさせた場合は「みなし譲渡」として所得税（譲渡所得税）が発生するケースがある。試験では受贈者の贈与税計算と贈与者の所得税両面から問われることがある。",
    exp3: "通常の不動産贈与は相続税評価額（路線価等）が基準だが、負担付贈与の場合は時価（実勢価格）が基準になる。この違いを必ず押さえること。",
