    exp1: "死因贈与とは、「自分が死んだら財産をあなたに贈与する」という贈与者の死亡を停止条件とする贈与契約。贈与契約の一種だが、死亡により効力が生じるため課税は相続税となる（みなし相続財産として扱われる）。遺言と異なり受贈者の合意（契約）が必要。遺言による遺贈に似ているが、遺言は単独行為、死因贈与は契約。",
