    exp1: "遺贈とは、遺言書によって遺産の全部または一部を特定の者（受遺者）に与えること。法定相続人以外の第三者（友人・医師・慈善団体・法人等）にも渡せる点が特徴。相続税は、受遺者が相続人であれば相続税の申告に含まれ、相続人以外の場合も相続税の対象（みなし相続財産）となる。",
