    exp1: "路線価方式では「路線価（千円単位）×奥行価格補正率×地積（㎡）」で評価額を計算する。路線価は国税庁が毎年公表し、単位は1,000円/㎡で表示（「300C」なら30万円/㎡）。奥行価格補正率は土地の奥行距離に応じて0.8〜1.0の範囲で適用。設例では30万円×0.98×120㎡＝3,528万円が評価額。さらに不整形地・側方路線等の補正が加わることもある。",
