    exp1: "長期優良住宅とは、長期にわたって良好な状態で使用できる住宅として、国土交通大臣の基準（耐震性・耐久性・省エネ性・維持管理のしやすさ等）を満たし所管行政庁の認定を受けた住宅。税制面での優遇措置として、住宅ローン控除の借入限度額の拡大・固定資産税の減額期間延長・不動産取得税の軽減等がある。フラット35Sの金利引き下げ期間も長くなる。",
