    exp1: "ZEH（ネット・ゼロ・エネルギー・ハウス）とは、断熱性能の強化（省エネ）と太陽光発電等（創エネ）を組み合わせることで、年間の一次エネルギー消費量の収支をゼロ以下にすることを目指した住宅。国の補助金や税制優遇（住宅ローン控除の借入限度額拡大）の対象となっており、新築住宅に対する普及政策が進められている。",
    exp2: "試験では「ZEHとは何か」という定義問題が出る。長期優良住宅・低炭素住宅・ZEHの3種類の違いを整理しておく。ZEH＝エネルギー収支ゼロ、長期優良住宅＝長持ちする家、低炭素住宅＝CO₂排出削減という切り口で区別する。",
