    exp1: "源泉徴収票とは、会社（給与支払者）が従業員（給与所得者）に対して交付する書類で、1年間の給与総額・所得控除額・源泉徴収税額・社会保険料額などが記載されている。確定申告が必要な場合（副業・医療費控除・住宅ローン初年度等）に使用するほか、金融機関のローン審査・保育所入所申請などの所得証明としても使われる。",
    exp2: "年末調整が完了している会社員は、原則として確定申告が不要だが、以下の場合は確定申告が必要：①給与収入が2000万円超、②2か所以上から給与を受けている、③医療費控除・寄附金控除等を受けたい場合、④副業所得が20万円超。",
    exp3: "「源泉徴収票＝確定申告の書類」という誤解がある。年末調整で精算済みの会社員には確定申告義務がなく、源泉徴収票は所得証明として使われることが多い。",
