    exp1: "マイナンバー（個人番号）は、日本に住民票を持つすべての人に付与された12桁の個人識別番号（2015年～）。利用範囲は社会保障（年金・医療・介護）・税（確定申告・源泉徴収）・災害対策の3分野。雇用時に勤務先への提供が必要で、確定申告書・源泉徴収票への記載も求められる。2024年から健康保険証との一体化（マイナ保険証）も進んでいる。",
