    exp1: "個人住民税は、前年（1月1日〜12月31日）の所得を基に計算され、翌年6月から翌々年5月にかけて徴収される「前年所得課税」の仕組みを採っている。税率は所得割が一律10%（都道府県民税4%＋市区町村民税6%）で、これに均等割（2026年現在、年額5,000円前後）が加わる形となる。給与所得者は会社が毎月給与から天引きする特別徴収が原則。",
    exp2: "試験では「所得税＝当年課税、住民税＝前年課税」という対比が頻出。退職した年の翌年6月に住民税の納付書が自宅に届く（普通徴収に切替わる）のは前年所得課税の結果であり、「なぜ退職後も住民税の請求が来るのか」という実務的な問いへの答えになる。",
    exp3: "「住民税＝今年の所得に課税」という誤解が典型的な引っかけ。「前年所得＝翌年課税」の時間ズレを意識して覚える。",
    svg: "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7f0\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">個人住民税 前年所得課税のしくみ</text>\n  <rect x=\"20\" y=\"38\" width=\"100\" height=\"36\" fill=\"#4caf50\" rx=\"5\"/>\n  <text x=\"70\" y=\"58\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\">2025年（前年）</text>\n  <text x=\"70\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\">所得が発生</text>\n  <rect x=\"180\" y=\"38\" width=\"100\" height=\"36\" fill=\"#388e3c\" rx=\"5\"/>\n  <text x=\"230\" y=\"58\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\">2026年6月〜</text>\n  <text x=\"230\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"white\">住民税徴収</text>\n  <line x1=\"122\" y1=\"56\" x2=\"178\" y2=\"56\" stroke=\"#2d6a2d\" stroke-width=\"2\" marker-end=\"url(#arr)\"/>\n  <defs><marker id=\"arr\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L0,6 L8,3 z\" fill=\"#2d6a2d\"/></marker></defs>\n  <text x=\"150\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" fill=\"#2d6a2d\">翌年課税</text>\n  <rect x=\"20\" y=\"95\" width=\"260\" height=\"30\" fill=\"#c8e6c9\" rx=\"5\"/>\n  <text x=\"150\" y=\"106\" text-anchor=\"middle\" font-size=\"10\" fill=\"#1b5e20\">所得割：一律10%（都道府県4%＋市区町村6%）</text>\n  <text x=\"150\" y=\"120\" text-anchor=\"middle\" font-size=\"10\" fill=\"#1b5e20\">均等割：年額約5,000円</text>\n  <rect x=\"20\" y=\"138\" width=\"260\" height=\"30\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"150\" y=\"153\" text-anchor=\"middle\" font-size=\"10\" fill=\"#1b5e20\">課税所得 × 10% ＋ 均等割 ＝ 年間住民税</text>\n  <text x=\"150\" y=\"168\" text-anchor=\"middle\" font-size=\"10\" fill=\"#1b5e20\">（例）課税所得300万円 → 30万円＋均等割</text>\n</svg>",
