    exp1: "復興特別所得税は、東日本大震災の復興財源を確保するために2013年から2037年までの25年間、基準所得税額に2.1%を上乗せして徴収する税。計算式は「基準所得税額×2.1%」。給与所得者は源泉徴収で自動的に差し引かれるため気づきにくいが、確定申告では所得税と一緒に計算・申告する必要がある。",
    exp2: "試験では「2.1%」「2037年まで」という数字と、「所得税額」に対する上乗せであることが問われる。「所得額の2.1%」「2027年まで」という数字の誤りに引っかからないよう注意。預金利子の源泉徴収税率が「15.315%」となっているのも所得税15%＋復興特別所得税0.315%の合算が理由。",
    exp3: "「所得金額」ではなく「所得税額」に乗じる点、期限が「2037年」である点の2つが頻出の引っかけポイント。",
