    exp1: "物納とは、相続税を金銭で一括納付することも延納（分割払い）でも困難な場合に、相続財産（不動産・国債・上場株式等）で相続税を納付できる制度。物納の順位は法令で定められており、第1順位が不動産・船舶・国債・地方債・上場株式等、第2順位が非上場株式等、第3順位が動産となる。物納財産は税務署が定める収納価額（相続税評価額）で納付に充てられる。",
    exp2: "試験では「延納の次の手段が物納」「金銭が用意できる場合は物納不可」「物納できる財産の種類（相続財産に限る）」が問われる。物納財産の収納価額は相続税評価額であり、時価より低い場合でも評価額で納付に充当される点も出題される。",
    exp3: "「現金があっても財産で払いたい」場合は物納選択不可。あくまでも「延納でも困難」が前提条件。",
