    q: "次の状況に当てはまるのは？",
    choices: [{"text":"幼稚園〜大学まで全て私立の場合、教育費の総額は2,000万円を超えるケースがある","correct":true},{"text":"幼稚園〜大学まで全て私立でも教育費の総額は500万円程度で収まる","correct":false,"hint":"私立一貫では学費だけで2,000万円超になることがある。文部科学省の調査でも確認できる。"}],
    exp1: "文部科学省の子供の学習費調査（2022年）によると、幼稚園〜大学まで全て私立の場合の教育費総額は約2,300万円前後、全て公立でも約770万円程度とされる。特に私立大学の費用（文系年間約115万円・理系年間約153万円）が大きく、4年間で500〜600万円を超えることも多い。進学先の公私立の選択が教育費計画に大きく影響する。",
