    exp1: "景気動向指数（DI・CI）は内閣府が毎月公表する景気の現状把握・将来予測のための総合的な統計。3系列に分かれており、①先行指数（新規求人数・消費者態度指数等）は景気の山・谷より数か月早く動く、②一致指数（鉱工業生産指数・有効求人倍率等）は景気と同時期に動く、③遅行指数（完全失業率・消費者物価指数等）は景気の動きに遅れて動く。",
