    exp1: "ノーロードファンドとは、投資信託を購入する際の「販売手数料（申込手数料）」が無料（ゼロ）の投資信託のこと。通常の投資信託は購入時に購入金額の0〜3%程度の手数料がかかる場合があるが、ノーロードファンドはこの負担がない。ただし保有中は年率0.1〜2%程度の「信託報酬（運用管理費用）」が毎日基準価額から差し引かれるため、信託報酬が低いかどうかも選択の重要ポイント。",
