    exp1: "信託報酬（運用管理費用）は、投資信託の運用・管理・販売に対して投資家が支払うコストで、純資産総額に対して年率で設定される（例：年率0.1%）。毎日の基準価額計算の際に日割りで自動的に差し引かれるため、投資家が別途払うわけではなく、気づかないうちに引かれている費用。信託報酬が高いと長期では大きなコスト差になるため、特に長期運用では低い信託報酬のファンドを選ぶことが重要。",
