    exp1: "基準価額とは、投資信託が保有する資産（株式・債券等）の時価合計（純資産総額）を、発行済み口数で割って1万口当たりに換算した価格。計算式：基準価額＝純資産総額÷総口数×10,000。運用の出来によって毎日変動し、資産価値の上昇・下落がそのまま反映される。投資信託の購入・売却（解約）時の価格の基準となるため「基準価額」と呼ばれる。",
    exp2: "試験では「基準価額の計算式」と「毎日変動する」という点が問われる。株式の株価と異なり、投資信託の基準価額は1日1回（原則として当日の取引終了後）に算出される「1日1価格」の仕組み。また投資信託は「口数」単位で取引され、口数×基準価額÷10,000＝投資金額となる。",
    exp3: "「基準価額は固定」は誤り。毎日変動する。また株価のように取引時間中にリアルタイムで変動するわけではなく、1日1回の算出となる点も覚える。",
