    exp1: "純資産総額（Net Asset Value, NAV）は、投資信託が保有する株式・債券・現金等のすべての資産を時価評価した合計金額から、負債を差し引いた金額。基準価額の算出基礎となる。純資産総額が大きいほどファンドの規模が大きく、①運用の安定性が高まる、②少額取引の影響を受けにくい、③繰上償還リスクが低い、といったメリットがある。逆に極端に小さいファンドは繰上償還（強制終了）のリスクがある。",
    exp2: "試験では「基準価額の算出に使われること」と「純資産総額が大きい＝規模が大きいファンド」という基本関係が問われる。純資産総額が急減しているファンドは運用環境の悪化または大量解約が起きている可能性があり、繰上償還の予兆となる場合もある。",
    exp3: "「確定利益の累計＝純資産総額」は誤り。純資産総額は現時点の保有資産の時価総額。毎日変動する。",
