    exp1: "オープンエンド型投資信託とは、投資家がいつでも運用会社（受託銀行経由）に対して解約請求を行い、基準価額に基づいて換金できる投資信託の形態。日本で販売されている大半の公募投資信託がこの形態をとる。解約請求があると、運用会社は保有資産を売却して資金を用意するため、大量解約が起きると運用に影響することがある。",
    exp2: "試験では「オープンエンド型は随時換金可」「日本の大半の投資信託がオープンエンド型」という2点が問われる。クローズドエンド型は換金が原則として市場での売却に限られ、運用会社への解約請求はできない。ETF（上場投資信託）はクローズドエンド型に分類される場合がある。",
    exp3: "「オープンエンド型は取引所でのみ売れる」は誤り。運用会社に直接解約請求することで換金できる点がオープンエンド型の特徴。",
