    exp1: "クローズドエンド型の投資信託は、投資家が換金する際に運用会社への解約請求ができず、市場（取引所）での売却によってのみ換金できる形態。上場しているETF（Exchange Traded Fund）がこの形態に近く、株式と同様に取引時間中にリアルタイムで売買できる。一方で解約請求ができないため、市場で買い手がいないと売却できない「流動性リスク」がある。",
