    exp1: "投資信託の分配金は2種類に区分される。①普通分配金：分配落ち後の基準価額が個別元本（投資家の取得価額）を上回っている場合に支払われる分配金で、配当所得として20.315%（所得税・住民税・復興特別所得税）が源泉徴収される。②特別分配金（元本払戻金）：分配落ち後の基準価額が個別元本を下回る場合に支払われる分配金で、投資家の個別元本の一部が戻ってきたものとみなされ、課税されない代わりに個別元本が減少する。",
