    exp1: "普通分配金とは、投資信託の分配落ち後の基準価額が投資家の個別元本（取得価額）を上回っている部分に相当する分配金。これは運用によって生み出された利益（収益）の分配であるため、配当所得として取り扱われ、20.315%（所得税15%＋住民税5%＋復興特別所得税0.315%）が源泉徴収される。申告不要制度（源泉分離課税）を選択すれば確定申告は不要。",
    exp2: "試験では「普通分配金＝課税（20.315%）」という税率と、特別分配金（非課税）との対比が問われる。NISA口座で保有する投資信託から受け取る分配金は、普通分配金であっても非課税になる点も重要ポイント。一般口座・特定口座の場合は普通分配金に税金がかかる。",
    exp3: "「普通分配金は非課税・申告が必要」の組合せは誤り。普通分配金は課税対象。申告不要制度を使えば確定申告不要だが、課税はされている。",
