    exp1: "リバランスとは、ポートフォリオの資産配分が市場変動によって当初の目標比率からずれた際に、売買を行って元の配分比率に戻す操作。値上がりした資産を一部売却し、値下がりした資産を買い増すことで、自動的に「高値売り・安値買い」ができるメリットがある。年1回または一定の乖離幅（±5%等）を超えたときに行う方法が一般的。",
    exp2: "試験では「リバランスの目的（配分を元に戻すこと）」と「値上がり分を売る・値下がり分を買う」という操作の方向性が問われる。リバランスは感情に左右されず規律ある運用を続けるための仕組みでもあり、長期分散投資の基本動作として重要。",
    exp3: "「値上がりした資産を追加購入」はリバランスではない。リバランスは値上がり分を売って配分を戻す操作で、「高値売り・安値買い」の原則に沿っている。",
