    exp1: "個人向け社債は、企業が個人投資家向けに発行する債券。国債より信用リスクが高い分、一般的に利率（クーポン）が高めに設定される。格付けが高い大企業の社債でも発行体の倒産リスクはゼロではなく、倒産した場合には元本の全部または一部が回収できない可能性がある。格付機関（S&P・ムーディーズ等）による信用格付けがリスク判断の目安となる。",
