    exp1: "不動産小口化商品とは、1つの不動産物件（オフィスビル・マンション等）を小口に分割し、複数の投資家が共同で出資する商品。1口100万円〜数百万円程度から投資でき、一棟買いに比べて少額で不動産投資が可能。代表的な形態は任意組合型（投資家が組合員として不動産を共有）と匿名組合型（投資家が事業者に出資）。相続税評価の観点から不動産の評価減を活用した節税商品としても注目される。",
