    exp1: "名目金利とは、インフレ率の影響を調整していない表面上の金利のこと。銀行の預金金利・住宅ローン金利・債券の利率など、通常公表される金利はすべて名目金利。これに対し実質金利は「名目金利－インフレ率」で求められ、購買力ベースでの実際の利回りを示す。フィッシャー方程式では「名目金利≒実質金利＋インフレ率」の関係が成立する。",
