    exp1: "実質金利は「名目金利－インフレ率」で算出される（フィッシャー方程式の簡略版）。例：名目金利0.5%、インフレ率2.0%なら実質金利＝0.5%－2.0%＝－1.5%。実質金利がマイナスになるということは、金利収入よりも物価上昇による購買力の低下が大きく、預金していると実質的に資産が目減りすることを意味する。インフレ局面では現金・預金の実質価値が低下する理由はここにある。",
