    keyword: "表面利回り・不動産投資・年間賃料",
    scenario: "不動産オーナーの橋本さんは、2,000万円のアパートを購入し、年間賃料収入が120万円得られる物件を検討している。不動産業者から「グロス利回りは6%です」と説明された。",
