    exp1: "保険には4つの基本原則がある。①利得禁止の原則：損害を超えた利益の取得を禁止する。②実損填補の原則：実際の損害額だけを補償する（損害保険中心）。③給付反対給付均等の原則：個々の保険契約者が払う保険料はリスクに見合ったものであるべき。④収支相等の原則：保険料の総収入と保険金の総支払が等しくなるよう設計する。",
