    exp1: "危険選択（リスク選択）は、保険会社が被保険者のリスクレベルを評価し、保険引受の可否や特別条件（保険料割増・特定部位不担保等）を決定するプロセスだ。主な方法として、①告知審査（質問書への回答）、②医的診査（医師による診察）、③財務的審査（高額保険金の場合）がある。",
    exp2: "危険選択の目的は、健康リスクが平均より著しく高い人を通常の保険料で引き受けることによる「逆選択（アドバース・セレクション）」を防ぐことだ。病気持ちの人ばかりが保険に加入すると、保険会社の損失が膨らみ保険制度が維持できなくなるため、適切なリスク評価が必要となる。",
    exp3: "「危険選択は加入者側の行為」という誤解に注意。危険選択は保険会社が実施する審査プロセス。告知義務は加入者側の義務だが、その告知内容をもとに危険選択を行うのは保険会社の側だ。加入者の行為（告知）と保険会社の行為（危険選択）を混同しないこと。",
