    exp3: "「疾病入院特約で交通事故入院も補償される」は誤り。疾病入院特約は「疾病（病気）専用」。事故による入院は傷害特約が必要。病気・事故両方の入院を一括して補償したい場合は医療保険単独加入が便利だ。",
