    exp1: "損害保険契約者保護機構は、損害保険会社の破綻時に契約者を保護する機関だ。補償率は保険の種類によって異なる。①自賠責保険・地震保険：100%補償。②破綻後3か月以内に保険事故が発生した場合：100%補償。③その他（破綻3か月経過後の事故等）：80%補償。",
    exp2: "自賠責保険が100%補償される理由は、被害者保護の公的性格が強い強制保険だからだ。また破綻直後3か月の100%補償は、代替保険への移行期間中の契約者保護を目的としている。FP3試験では「自賠責は100%・その他は80%」という数字の対比が頻出問題となっている。",
    exp3: "「損保も90%補償」は誤り。損保は100%と80%の2段階。生保（90%）との混同に注意。また「自賠責は強制保険なので保護機構の対象外」と誤解する場合があるが、自賠責は保護機構で100%補償される代表例だ。",
